pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(uint160(actor) > 100);
        // adversarial counterparty: accepts only zero-value transfers
        NonZeroReverter recipient = new NonZeroReverter();

        vm.deal(address(c), 1 ether);

        // give the recipient a reward via the public entry
        vm.prank(actor);
        c.getFirstWithdrawalBonus(address(recipient));

        // drain the reward once (succeeds in both P and M since c is funded)
        c.withdrawReward(address(recipient));

        // second withdrawal must pay zero, so even a receiver that rejects
        // nonzero value accepts it (holds in P; in M it re-pays 100 and reverts)
        bool ok;
        try c.withdrawReward(address(recipient)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract NonZeroReverter {
    fallback() external payable {
        require(msg.value == 0);
    }
}

