pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    OnceReceiver recipient;

    function setUp() public {
        c = new C();
        recipient = new OnceReceiver();
    }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1 ether);
        vm.deal(address(c), amount);

        // First withdrawal: succeeds and pays `amount`; receiver accepts it once.
        c.withdrawReward(address(recipient));

        // Second withdrawal: reference zeroes the reward, so it transfers 0 and
        // succeeds even though the receiver rejects any nonzero payment.
        bool ok;
        try c.withdrawReward(address(recipient)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}

contract OnceReceiver {
    uint256 received;
    receive() external payable {
        require(received == 0, "only once");
        received += msg.value;
    }
}

