pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialBalance) public {
        initialBalance = bound(initialBalance, 1000, 1e24);
        vm.deal(address(c), initialBalance);
        attacker = new Attacker(c);
        attacker.attack();
        // Rule: the reward is zeroed before the payout, so the re-entrant
        // withdrawReward inside the transfer sends nothing extra; the contract
        // loses exactly the 100-wei bonus once.
        assertTrue(address(c).balance == initialBalance - 100);
    }
}

contract Attacker {
    C c;
    bool reentered;

    constructor(C _c) { c = _c; }

    function attack() external {
        c.getFirstWithdrawalBonus(address(this));
    }

    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawReward(address(this));
        }
    }
}

