pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address recipient) public {
        // recipient must be a plain account so the 100-wei payout always succeeds
        vm.assume(recipient.code.length == 0);

        // fund the contract so all payouts can succeed in both versions
        vm.deal(address(c), 1 ether);

        // one-time bonus: rewards 100 wei to recipient and immediately withdraws it
        c.getFirstWithdrawalBonus(recipient);

        uint256 balAfterBonus = address(c).balance;

        // a repeat withdrawal must be a no-op: the reward was already zeroed,
        // so the contract's balance must not change any further.
        c.withdrawReward(recipient);

        assertTrue(address(c).balance == balAfterBonus);
    }
}

