pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    ReentrantAttacker atk;

    function setUp() public {
        c = new C();
        atk = new ReentrantAttacker(c);
        vm.deal(address(c), 10 ether);
    }

    function testFuzz_property(uint256 mode, uint256 seed) public {
        bool reenter = (mode % 2 == 1);
        atk.setReenter(reenter, seed);
        bool ok;
        try c.getFirstWithdrawalBonus(address(atk)) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a recipient that reenters c during the payout must never
        // see the outer call complete successfully (reentrancy is rejected).
        assertTrue(!(reenter && ok));
    }
}

contract ReentrantAttacker {
    C c;
    bool reenter;
    uint256 noise;

    constructor(C _c) {
        c = _c;
    }

    function setReenter(bool _reenter, uint256 _noise) external {
        reenter = _reenter;
        noise = _noise;
    }

    receive() external payable {
        if (reenter) {
            c.withdrawReward(address(this));
        }
    }
}

