pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(c) && actor != address(this));

        // Adversarial counterparty: a re-entrant recipient that, while being paid,
        // calls back into c.getFirstWithdrawalBonus (nested bonus + nested payout).
        Reentrant recipient = new Reentrant(c);

        vm.deal(address(c), 1 ether);

        bool ok;
        vm.prank(actor);
        try c.getFirstWithdrawalBonus(address(recipient)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a bonus claim by any caller against a re-entrant recipient
        // must fail (the lock rejects the nested withdrawal). The mutant, having
        // removed require(!_locked), lets the whole nested claim succeed.
        assertTrue(!ok, "reentrant bonus claim must be rejected");
    }
}

contract Reentrant {
    C c;
    constructor(C _c) { c = _c; }

    receive() external payable {
        c.getFirstWithdrawalBonus(address(this));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function test(address r) public {
        // rewardsForA[r] is 0, so the external 0-value call succeeds.
        // P: require(success) passes, lock is released.
        // M: require(!success) fails, so this call reverts.
        c.withdrawReward(r);

        // A completed withdrawReward must always release the reentrancy lock.
        assert(!c._locked());
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function run(address recipient) public {
        c.getFirstWithdrawalBonus(recipient);
        (bool ok, ) = address(c).call(
            abi.encodeWithSelector(c.getFirstWithdrawalBonus.selector, recipient)
        );
        assert(!ok);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function check(address recipient) public {
        bool reverted = false;
        try c.getFirstWithdrawalBonus(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    receive() external payable {}

    function t() public {
        uint balC = address(c).balance;
        require(balC >= 100);
        c.getFirstWithdrawalBonus(address(this));
        assert(address(this).balance == balC - address(c).balance + balC && address(this).balance - 0 == balC + (balC - address(c).balance));
    }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function check(uint256 amount) public {
        require(amount >= 100);
        require(address(this).balance >= amount);
        (bool ok, ) = payable(address(c)).call{value: amount}("");
        require(ok);
        uint256 before = address(this).balance;
        c.getFirstWithdrawalBonus(address(this));
        assert(address(this).balance == before + 100);
    }

    receive() external payable {}
}
